/**
 * A token's symbol, name and decimals. These practically never change, so the
 * portfolio remembers them and asks the chain for balances alone on later updates.
 */
export type TokenMetadataEntry = {
  symbol: string
  name: string
  decimals: number
  /**
   * When the metadata was last read from the chain. Entries older than
   * TOKEN_METADATA_MAX_AGE_MS are read again.
   */
  fetchedAt: number
}

/**
 * A collection's name and symbol. Kept apart from TokenMetadataEntry as collections
 * have no decimals.
 */
export type CollectionMetadataEntry = {
  symbol: string
  name: string
  /**
   * When the metadata was last read from the chain. Entries older than
   * TOKEN_METADATA_MAX_AGE_MS are read again.
   */
  fetchedAt: number
}

/**
 * Token metadata for a single network, keyed by checksummed token address.
 */
export type KnownTokenMetadata = Map<string, TokenMetadataEntry>

/**
 * Collection metadata for a single network, keyed by checksummed collection address.
 */
export type KnownCollectionMetadata = Map<string, CollectionMetadataEntry>

/**
 * What getTokens and getNFTs need in order to ask the chain for balances alone.
 * `needsMetadata` holds the addresses whose metadata must be read on this update,
 * computed once up front so every page of the same update agrees on it.
 */
export type AssetMetadataFetchPlan<T> = {
  known: Map<string, T>
  needsMetadata: Set<string>
}

export type TokenMetadataFetchPlan = AssetMetadataFetchPlan<TokenMetadataEntry>

export type CollectionMetadataFetchPlan = AssetMetadataFetchPlan<CollectionMetadataEntry>

/**
 * ERC-721 hints, returned by the Velcro API
 * Their structure is different and more complex than the structure
 * we use in the extension
 */
export interface VelcroERC721Hints {
  [collectionAddress: string]:
    | {
        isKnown: boolean
        enumerable: boolean
      }
    | {
        isKnown: boolean
        tokens: string[]
      }
}

/**
 * ERC-721 hints, used by the portfolio
 * [collectionAddress]: the ids of the collectibles in the collection.
 */
export interface ERC721s {
  [collectionAddress: string]: bigint[]
}

export type ExternalAPITokenMarketDataResponse = {
  /**
   * The relayer returns baseCurrency and price, while cena returns only usd.
   */
  baseCurrency?: string
  /**
   * The relayer returns the price in [price]
   */
  price?: number
  /**
   * cena returns the price in [usd]
   */
  usd?: number
  /**
   * Despite the name, this is a percentage, not USD value change.
   */
  usd_fully_diluted_valuation?: number
  usd_24h_change: number
  usd_market_cap: number
  usd_24h_vol: number
  total_supply?: number
  exchanges: string[]
  homepage?: string[]
}

/**
 * The portfolio fetches tokens using deployless. We provide
 * "hints" to deployless, so it knows where to look for assets. Hints are
 * assets of different standards that the user is likely to have. They come from
 * different sources, like:
 * - Velcro - our external API for hints
 * - Custom tokens (ERC-20 only atm)
 * - Token preferences (ERC-20 only atm)
 * - Learned assets - see `LearnedAssets` for more info
 */
export interface Hints {
  erc20s: string[]
  erc721s: ERC721s
  /**
   * Metadata and prices from the Velcro API call
   */
  externalApi?: {
    /**
     * When hasHints is false and the list is generated from a top X list,
     * the prices are coming together with the hints as the response contains
     * prices for all tokens in the hints. In this case the extension should
     * not make separate requests for prices.
     */
    prices: {
      [addr: string]: ExternalAPITokenMarketDataResponse
    }
    /**
     * When true, either the account is empty and static hints are returned,
     * or the hints are coming from a top X list of tokens, sorted by market cap.
     * Used to determine how often to refetch the hints.
     */
    hasHints: boolean
    /**
     * Attached by the application after the request response or, if there is an
     * error or the request is skipped, we get it from the last call.
     */
    lastUpdate: number
  }
}

/**
 * The raw response, returned by the Velcro API.
 * Currently only called by the portfolio lib to fetch hints only.
 */
export type ExternalHintsAPIResponse = {
  erc20s: Hints['erc20s']
  erc721s: VelcroERC721Hints
} & (Required<Hints['externalApi']> & {
  error?: string
})

/**
 * The raw response, returned by Velcro for portfolio discovery.
 * It contains hints and defi positions. Used by the controller.
 */
export type ExternalPortfolioDiscoveryResponse = {
  networkId: string
  chainId: number | 'customAppChain'
  accountAddr: string
  erc20s: ExternalHintsAPIResponse['erc20s']
  erc721s: ExternalHintsAPIResponse['erc721s']
  hasHints: ExternalHintsAPIResponse['hasHints']
  prices: ExternalHintsAPIResponse['prices']
  lastUpdate: ExternalHintsAPIResponse['lastUpdate']
  defi:
    | {
        positions: Omit<PositionsByProvider, 'source'>[]
        updatedAt: number
      }
    | {
        success: false
        errorState: {
          message: string
          level: 'fatal'
        }[]
      }
  /**
   * The count of defi positions on networks that weren't requested.
   * Used to inform the user about positions on disabled networks.
   */
  otherNetworksDefiCounts: {
    [chainId: string]: number
  }
}

export type FormattedPortfolioDiscoveryResponse = {
  data: {
    hints: FormattedExternalHintsAPIResponse | null
    defi: {
      positions: PositionsByProvider[]
      updatedAt: number
      isForceUpdate: boolean
    } | null
    /**
     * The count of defi positions on networks that weren't requested.
     * Used to inform the user about positions on disabled networks.
     */
    otherNetworksDefiCounts: {
      [chainId: string]: number
    }
  } | null
  discoveryTime: number
  errors: ExtendedErrorWithLevel[]
}

/**
 * A stripped version of `ExternalHintsAPIResponse`. Also, ERC-721 hints
 * are formatted to be in the structure, expected by the extension.
 */
export type FormattedExternalHintsAPIResponse = {
  erc20s: Hints['erc20s']
  erc721s: Hints['erc721s']
  lastUpdate: ExternalHintsAPIResponse['lastUpdate']
  hasHints: ExternalHintsAPIResponse['hasHints']
}

